TOOLS_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>AgentWhite Tool Registry</title>
<style>
:root{--bg:#07100d;--panel:#0d1915;--panel2:#11231d;--line:#1e3a30;--text:#d9f8e8;--muted:#83a795;--green:#5dffa7;--amber:#ffcc66;--red:#ff6b6b;--blue:#79c9ff}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#10261e 0,var(--bg) 40%);color:var(--text);font:14px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace;min-height:100vh}.shell{max-width:1300px;margin:auto;padding:22px}.top,.row,.filters,.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:14px}.brand{font-size:24px;font-weight:800;letter-spacing:1px}.brand span{color:var(--green)}.btn,button{border:1px solid #2d624c;background:#10291f;color:var(--text);padding:8px 11px;border-radius:8px;cursor:pointer;text-decoration:none}.btn:hover,button:hover{border-color:var(--green);color:var(--green)}button.primary{color:var(--green);border-color:#347d58}button:disabled{cursor:not-allowed;opacity:.4}.panel{background:rgba(13,25,21,.94);border:1px solid var(--line);border-radius:12px;overflow:hidden;margin-bottom:14px}.head{padding:13px 15px;border-bottom:1px solid var(--line)}.body{padding:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}@media(max-width:850px){.grid{grid-template-columns:1fr}}.card{border:1px solid var(--line);background:var(--panel2);border-radius:10px;padding:12px}.title{font-weight:800;font-size:15px}.muted{color:var(--muted)}.badge{font-size:10px;padding:3px 6px;border:1px solid var(--line);border-radius:999px;text-transform:uppercase}.badge.ok{color:var(--green);border-color:#347d58}.badge.warn{color:var(--amber)}.badge.bad{color:var(--red)}.right{margin-left:auto}.meta{display:flex;gap:6px;flex-wrap:wrap;margin:9px 0}.chip{font-size:11px;padding:4px 6px;background:#09140f;border:1px solid #183127;border-radius:6px;color:var(--muted)}.policy{margin-top:9px;padding:8px;background:#050b08;border:1px solid #172a22;border-radius:7px;color:#abd5c0}.empty{padding:24px;text-align:center;color:var(--muted)}input{background:#050b08;color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px;min-width:240px}.summary{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.adapter{margin-top:10px;padding-top:10px;border-top:1px solid var(--line)}.adapter-row{background:#09140f;border:1px solid #183127;border-radius:8px;padding:9px;margin-top:7px}.history{border-left:3px solid var(--blue)}pre{white-space:pre-wrap;word-break:break-word;background:#050b08;border:1px solid #172a22;padding:8px;border-radius:7px;color:#abd5c0;max-height:260px;overflow:auto}.modal{display:none;position:fixed;inset:0;background:#000b;z-index:20;padding:20px;align-items:center;justify-content:center}.modal.open{display:flex}.modal-card{width:min(980px,100%);max-height:92vh;overflow:auto;background:#09140f;border:1px solid #2e5946;border-radius:12px}.modal-head{position:sticky;top:0;background:#09140f;padding:12px;border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center}.modal-head strong{flex:1}.modal-body{padding:12px}.toast{position:fixed;right:16px;bottom:16px;background:#10291f;border:1px solid #347d58;padding:10px;border-radius:8px;display:none;max-width:440px}.toast.error{background:#2a1515;border-color:#844}
</style>
</head>
<body>
<div class="shell">
  <div class="top"><div><div class="brand">AGENT<span>WHITE</span> · TOOL REGISTRY</div><div class="muted">Fixed adapters only. Every recipe stops when finished; no external engine can auto-chain.</div></div><a class="btn" href="/">Back to Dashboard</a></div>
  <div class="panel">
    <div class="head"><div class="row"><strong>CURATED TOOL PACK</strong><span class="right muted" id="count">Loading…</span></div></div>
    <div class="body">
      <div class="summary" id="summary"></div>
      <div class="filters"><input id="search" placeholder="Filter tools, protocols, hardware…" oninput="renderTools()"/><button onclick="setMode('all')">All</button><button onclick="setMode('installed')">Installed</button><button onclick="setMode('missing')">Missing</button></div>
      <div id="tools" class="grid" style="margin-top:12px"><div class="empty">Loading registry…</div></div>
    </div>
  </div>
  <div class="panel">
    <div class="head"><div class="row"><strong>TOOL HISTORY</strong><span class="right muted">Saved locally · newest first</span></div></div>
    <div class="body" id="history"><div class="empty">No tool actions have been run yet.</div></div>
  </div>
</div>
<div id="result-modal" class="modal" onclick="if(event.target===this)closeResult()"><div class="modal-card"><div class="modal-head"><strong id="result-title">TOOL RESULT</strong><button onclick="closeResult()">Close</button></div><div class="modal-body"><div id="result-meta" class="policy"></div><pre id="result-body"></pre></div></div></div>
<div id="toast" class="toast"></div>
<script>
let state={tools:[],actions:[],runs:[]};let mode='all';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function toast(msg,error=false){const e=document.getElementById('toast');e.textContent=msg;e.className='toast'+(error?' error':'');e.style.display='block';setTimeout(()=>e.style.display='none',3500)}
function setMode(v){mode=v;renderTools()}
async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},cache:'no-store',...opts});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||('Request failed: '+r.status));return d}
async function load(){state=await api('/api/tools');render()}
function render(){document.getElementById('count').textContent=(state.tools||[]).length+' registered tools';renderTools();renderHistory()}
function toolActions(id){return (state.actions||[]).filter(a=>a.tool_id===id)}
function renderTools(){const rows=state.tools||[];const q=(document.getElementById('search').value||'').toLowerCase();let view=rows.filter(x=>mode==='all'||(mode==='installed'&&x.installed)||(mode==='missing'&&!x.installed));view=view.filter(x=>JSON.stringify(x).toLowerCase().includes(q));const installed=rows.filter(x=>x.installed).length;const ready=(state.actions||[]).filter(a=>a.available).length;document.getElementById('summary').innerHTML=`<span class="badge ok">${installed} tools detected</span><span class="badge ok">${ready} approved actions ready</span><span class="badge">${rows.length-installed} not detected</span><span class="badge warn">AUTO-CHAIN DISABLED</span>`;document.getElementById('tools').innerHTML=view.length?view.map(x=>{const acts=toolActions(x.id);const actionHtml=acts.length?`<div class="adapter"><strong>AgentWhite adapters</strong>${acts.map(a=>`<div class="adapter-row"><div class="row"><div><div class="title">${esc(a.label)}</div><div class="muted">${esc(a.description)}</div></div><span class="right badge ok">${esc(a.effect)}</span></div><div class="actions" style="margin-top:7px"><button class="primary" ${a.available?'':'disabled'} onclick="runAction('${esc(a.id)}')">${a.available?'Run This Action':'Tool Not Detected'}</button><span class="chip">fixed args only</span><span class="chip">stops after result</span></div></div>`).join('')}</div>`:'';return `<div class="card"><div class="row"><div><div class="title">${esc(x.name)}</div><div class="muted">${esc(x.category)} · ${esc(x.project)}</div></div><span class="right badge ${x.installed?'ok':'warn'}">${x.installed?'DETECTED':'NOT DETECTED'}</span></div><div class="meta"><span class="chip">${esc(x.effect)}</span><span class="chip">${esc(x.integration)}</span><span class="chip">${esc(x.bundle_policy)}</span>${(x.platforms||[]).map(p=>`<span class="chip">${esc(p)}</span>`).join('')}</div><div><strong>Capabilities</strong><div class="muted">${esc((x.capabilities||[]).join(' · '))}</div></div><div style="margin-top:7px"><strong>Hardware</strong><div class="muted">${esc((x.hardware||[]).join(' · ')||'No dedicated hardware requirement')}</div></div><div style="margin-top:7px"><strong>License note</strong><div class="muted">${esc(x.license_hint)}</div></div>${x.detected?.length?`<div style="margin-top:7px"><strong>Detected at</strong><div class="muted">${esc(x.detected.join(' · '))}</div></div>`:''}<div class="policy">Enrollment required for active target tests: ${x.policy.requires_enrollment?'YES':'NO'} · Auto-chain: ${x.policy.auto_chain?'YES':'NO'} · Save evidence/results: ${x.policy.persist_results?'YES':'NO'}</div>${actionHtml}</div>`}).join(''):'<div class="empty">No tools match this filter.</div>'}
async function runAction(id){toast('Running only the selected fixed adapter…');try{const d=await api('/api/tool-action',{method:'POST',body:JSON.stringify({action_id:id})});state={tools:d.tools||state.tools,actions:d.actions||state.actions,runs:d.runs||state.runs};render();showResult(d);toast('Action finished and saved. AgentWhite did not start another action.')}catch(e){toast(e.message,true);await load()}}
function showResult(d){const r=d.result||{};document.getElementById('result-title').textContent=r.label||'TOOL RESULT';document.getElementById('result-meta').textContent=`Status: ${d.status||'complete'} · ${d.elapsed_ms??0} ms · Auto-chain: OFF · Next action started: ${d.next_action_started?'YES':'NO'}`;document.getElementById('result-body').textContent=JSON.stringify(r.result||r,null,2);document.getElementById('result-modal').classList.add('open')}
function closeResult(){document.getElementById('result-modal').classList.remove('open')}
function renderHistory(){const rows=state.runs||[];const el=document.getElementById('history');if(!rows.length){el.innerHTML='<div class="empty">No tool actions have been run yet.</div>';return}el.innerHTML=rows.map(r=>`<div class="card history"><div class="row"><div><div class="title">${esc(r.label)}</div><div class="muted">${esc(r.tool_id)} · ${esc(r.action_id)} · ${esc(r.started_at)}</div></div><span class="right badge ${r.status==='success'?'ok':r.status==='failed'?'bad':'warn'}">${esc(r.status)}</span></div><div class="meta"><span class="chip">${esc(r.effect)}</span><span class="chip">${esc(r.scope)}</span><span class="chip">${r.elapsed_ms} ms</span></div><div class="actions"><button onclick='showSaved(${JSON.stringify(r.id)})'>View Saved Result</button></div></div>`).join('')}
function showSaved(id){const r=(state.runs||[]).find(x=>x.id===id);if(!r)return;document.getElementById('result-title').textContent=r.label;document.getElementById('result-meta').textContent=`Saved result · ${r.status} · ${r.elapsed_ms} ms · ${r.started_at}`;document.getElementById('result-body').textContent=JSON.stringify(r.result||{},null,2);document.getElementById('result-modal').classList.add('open')}
load().catch(e=>{document.getElementById('tools').innerHTML='<div class="empty">'+esc(e.message)+'</div>';toast(e.message,true)});
</script>
</body>
</html>'''
